import sys

def single_number_brute(nums):
    from collections import Counter
    cnt = Counter(nums)
    for k, v in cnt.items():
        if v == 1:
            return k
    return 0

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(single_number_brute(nums))

import sys

def single_number_opt(nums):
    ans = 0
    for i in range(32):
        bit = 0
        for x in nums:
            bit += (x >> i) & 1
        if bit % 3:
            ans |= 1 << i
    if ans >= 1 << 31:
        ans -= 1 << 32
    return ans

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(single_number_opt(nums))
